function icon(name, size) {
  const raw = window.ICONS[name];
  if (!raw) return document.createTextNode('');
  const sp = document.createElement('span'); sp.className = 'ico'; sp.innerHTML = raw;
  if (size) { sp.style.fontSize = size + 'px'; }
  return sp;
}
